void prepareToProcess(number sampleRate, Index maxBlockSize, bool force) {
    RNBO_ASSERT(this->_isInitialized);

    if (this->maxvs < maxBlockSize || !this->didAllocateSignals) {
        Index i;

        for (i = 0; i < 25; i++) {
            this->signals[i] = resizeSignal(this->signals[i], this->maxvs, maxBlockSize);
        }

        this->ip_01_sigbuf = resizeSignal(this->ip_01_sigbuf, this->maxvs, maxBlockSize);
        this->ip_02_sigbuf = resizeSignal(this->ip_02_sigbuf, this->maxvs, maxBlockSize);
        this->globaltransport_tempo = resizeSignal(this->globaltransport_tempo, this->maxvs, maxBlockSize);
        this->globaltransport_state = resizeSignal(this->globaltransport_state, this->maxvs, maxBlockSize);
        this->zeroBuffer = resizeSignal(this->zeroBuffer, this->maxvs, maxBlockSize);
        this->dummyBuffer = resizeSignal(this->dummyBuffer, this->maxvs, maxBlockSize);
        this->didAllocateSignals = true;
    }

    const bool sampleRateChanged = sampleRate != this->sr;
    const bool maxvsChanged = maxBlockSize != this->maxvs;
    const bool forceDSPSetup = sampleRateChanged || maxvsChanged || force;

    if (sampleRateChanged || maxvsChanged) {
        this->vs = maxBlockSize;
        this->maxvs = maxBlockSize;
        this->sr = sampleRate;
        this->invsr = 1 / sampleRate;
    }

    this->ip_01_dspsetup(forceDSPSetup);
    this->gen_01_dspsetup(forceDSPSetup);
    this->gen_08_dspsetup(forceDSPSetup);
    this->gen_06_dspsetup(forceDSPSetup);
    this->gen_09_dspsetup(forceDSPSetup);
    this->gen_10_dspsetup(forceDSPSetup);
    this->gen_07_dspsetup(forceDSPSetup);
    this->gen_05_dspsetup(forceDSPSetup);
    this->gen_03_dspsetup(forceDSPSetup);
    this->gen_02_dspsetup(forceDSPSetup);
    this->gen_04_dspsetup(forceDSPSetup);
    this->metertilde_01_dspsetup(forceDSPSetup);
    this->metertilde_02_dspsetup(forceDSPSetup);
    this->ip_02_dspsetup(forceDSPSetup);
    this->gen_11_dspsetup(forceDSPSetup);
    this->gen_13_dspsetup(forceDSPSetup);
    this->gen_16_dspsetup(forceDSPSetup);
    this->gen_17_dspsetup(forceDSPSetup);
    this->gen_18_dspsetup(forceDSPSetup);
    this->gen_14_dspsetup(forceDSPSetup);
    this->gen_12_dspsetup(forceDSPSetup);
    this->gen_20_dspsetup(forceDSPSetup);
    this->gen_15_dspsetup(forceDSPSetup);
    this->gen_19_dspsetup(forceDSPSetup);
    this->metertilde_05_dspsetup(forceDSPSetup);
    this->metertilde_06_dspsetup(forceDSPSetup);
    this->metertilde_04_dspsetup(forceDSPSetup);
    this->metertilde_03_dspsetup(forceDSPSetup);
    this->globaltransport_dspsetup(forceDSPSetup);

    if (sampleRateChanged)
        this->onSampleRateChanged(sampleRate);
}

number msToSamps(MillisecondTime ms, number sampleRate) {
    return ms * sampleRate * 0.001;
}

MillisecondTime sampsToMs(SampleIndex samps) {
    return samps * (this->invsr * 1000);
}

Index getNumInputChannels() const {
    return 2;
}

Index getNumOutputChannels() const {
    return 2;
}

